-- SIMS database export (MySQL 8). Schema + seed data matching database/migrations and DatabaseSeeder.
-- Import: mysql -u root -p < database/sims_export.sql   (creates database `sims`)
CREATE DATABASE IF NOT EXISTS `sims` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `sims`;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `enrollments`,`students`,`subjects`,`users`,`migrations`;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE `migrations` (`id` int unsigned NOT NULL AUTO_INCREMENT, `migration` varchar(255) NOT NULL, `batch` int NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `users` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `name` varchar(255) NOT NULL, `email` varchar(255) NOT NULL, `email_verified_at` timestamp NULL DEFAULT NULL, `password` varchar(255) NOT NULL, `role` varchar(20) NOT NULL DEFAULT 'staff', `api_token` varchar(64) DEFAULT NULL, `remember_token` varchar(100) DEFAULT NULL, `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `users_email_unique` (`email`), UNIQUE KEY `users_api_token_unique` (`api_token`), KEY `users_role_index` (`role`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `students` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `student_number` varchar(20) NOT NULL, `first_name` varchar(100) NOT NULL, `last_name` varchar(100) NOT NULL, `email` varchar(255) NOT NULL, `course` varchar(100) NOT NULL, `year_level` tinyint unsigned NOT NULL, `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `students_student_number_unique` (`student_number`), UNIQUE KEY `students_email_unique` (`email`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `subjects` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `code` varchar(20) NOT NULL, `name` varchar(150) NOT NULL, `units` tinyint unsigned NOT NULL, `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `subjects_code_unique` (`code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `enrollments` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `student_id` bigint unsigned NOT NULL, `subject_id` bigint unsigned NOT NULL, `school_year` varchar(9) NOT NULL, `semester` varchar(10) NOT NULL, `status` varchar(15) NOT NULL DEFAULT 'enrolled', `grade` decimal(3,2) DEFAULT NULL, `created_at` timestamp NULL DEFAULT NULL, `updated_at` timestamp NULL DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `enrollment_unique_term` (`student_id`,`subject_id`,`school_year`,`semester`), KEY `enrollments_subject_id_foreign` (`subject_id`), CONSTRAINT `enrollments_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE, CONSTRAINT `enrollments_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `migrations` (`migration`,`batch`) VALUES ('2026_01_01_000001_create_users_table',1),('2026_01_01_000002_create_students_table',1),('2026_01_01_000003_create_subjects_table',1),('2026_01_01_000004_create_enrollments_table',1);
